import { rootToLeaf } from 'pouchdb-merge';

/**
 * Adds _revisions to a doc.
 */
function processRevsRevsInfo(id, doc, rev_tree, opts) {
  var splittedRev = doc._rev.split('-');
  var revNo       = parseInt(splittedRev[0], 10);
  var revHash     = splittedRev[1];

  var paths = rootToLeaf(rev_tree);
  var path = null;

  for (var i = 0; i < paths.length; i++) {
    var currentPath = paths[i];
    var hashIndex = currentPath.ids.map(function (x) { return x.id; })
      .indexOf(revHash);
    var hashFoundAtRevPos = hashIndex === (revNo - 1);

    if (hashFoundAtRevPos || (!path && hashIndex !== -1)) {
      path = currentPath;
    }
  }

  /* istanbul ignore if */
  if (!path) {
    const err = new Error('invalid rev tree');
    err.docId = id;
    throw err;
  }

  var indexOfRev = path.ids.map(function (x) { return x.id; })
    .indexOf(doc._rev.split('-')[1]) + 1;
  var howMany = path.ids.length - indexOfRev;
  path.ids.splice(indexOfRev, howMany);
  path.ids.reverse();

  if (opts.revs) {
    doc._revisions = {
      start: (path.pos + path.ids.length) - 1,
      ids: path.ids.map(function (rev) {
        return rev.id;
      })
    };
  }
  if (opts.revs_info) {
    var pos =  path.pos + path.ids.length;
    doc._revs_info = path.ids.map(function (rev) {
      pos--;
      return {
        rev: pos + '-' + rev.id,
        status: rev.opts.status
      };
    });
  }
}

export default processRevsRevsInfo;
